"""Literal offline Malayalam rows for the user agreement."""

AGREEMENT_MALAYALAM_ROWS: dict[str, tuple[str, ...]] = {
    "ml": (
        "ഉപയോക്തൃ കരാർ",
        "Go and Help ഉപയോഗിക്കുമ്പോൾ നിങ്ങൾ അംഗീകരിക്കുന്ന നിബന്ധനകൾ.",
        "1 ജൂൺ 2024ന് പുതുക്കിയതും പ്രാബല്യത്തിൽ വന്നതും",
        "Go and Help ഒരു പ്ലാറ്റ്ഫോമും ഇടനിലക്കാരനും മാത്രമാണ്. ഏതെങ്കിലും ഉപയോക്താവിനെയോ ജോലിയെയോ പ്രതിഫലത്തെയോ കൂടിക്കാഴ്ചയെയോ ഞങ്ങൾ പരിശോധിക്കുകയോ മേൽനോട്ടം വഹിക്കുകയോ ജോലിക്കെടുക്കുകയോ ഉറപ്പുനൽകുകയോ ചെയ്യുന്നില്ല. ഇവിടെ നിങ്ങൾ ക്രമീകരിക്കുന്നതെല്ലാം മറ്റൊരു സ്വതന്ത്ര മുതിർന്നയാളുമായി നിങ്ങളുടെ സ്വന്തം ഉത്തരവാദിത്തത്തിലാണ്.",
        "Go and Help എന്താണ് — എന്തല്ല",
        "പ്രായപൂർത്തിയായവർ പ്രായോഗിക സഹായത്തിനുള്ള അഭ്യർഥനകൾ പ്രസിദ്ധീകരിക്കുകയും പരസ്പരം കണ്ടെത്തുകയും ചെയ്യുന്ന ഇടമാണ് Go and Help. പരസ്യപ്പെടുത്തൽ, ഭൂപടം, സന്ദേശം, ഫോറം എന്നീ ഉപകരണങ്ങൾ ഞങ്ങൾ നൽകുന്നു. അതാണ് ഞങ്ങളുടെ മുഴുവൻ പങ്ക്.",
        "ഉപയോക്താക്കൾ തമ്മിലുള്ള ഒരു ക്രമീകരണത്തിലും ഞങ്ങൾ കക്ഷിയല്ല. ഞങ്ങൾ തൊഴിൽദാതാവോ തൊഴിൽ ഏജൻസിയോ സ്റ്റാഫിങ് ഏജൻസിയോ കരാറുകാരനോ ഇൻഷുറൻസ് സ്ഥാപനമോ എസ്ക്രോ സേവനമോ പശ്ചാത്തല പരിശോധനാ സേവനമോ യാത്രാ ഏജന്റോ മേൽനോട്ടക്കാരനോ അല്ല. തിരിച്ചറിയൽ രേഖകൾ, യോഗ്യതകൾ, ലൈസൻസുകൾ, ഇൻഷുറൻസ്, ക്രിമിനൽ രേഖകൾ, കുടിയേറ്റനില, നികുതി നില എന്നിവ പരിശോധിക്കുന്നില്ല; പോസ്റ്റിലോ പ്രൊഫൈലിലോ എഴുതിയ കാര്യങ്ങൾ സത്യമാണെന്നും സ്ഥിരീകരിക്കുന്നില്ല.",
        "അർഹത",
        "നിങ്ങൾക്ക് കുറഞ്ഞത് 16 വയസ്സുണ്ടായിരിക്കണം; ഈ കരാറിൽ പ്രവേശിക്കാൻ നിയമപരമായ ശേഷിയും വേണം. ഒരാൾക്ക് ഒരു അക്കൗണ്ട് മാത്രം. കോടതി ഉത്തരവോ ഉപരോധനിയമമോ ബാധകമായ നിയമമോ Go and Help ഉപയോഗിക്കുന്നത് വിലക്കിയിട്ടുണ്ടെങ്കിൽ, അല്ലെങ്കിൽ നിങ്ങളുടെ പ്രവേശനം മുമ്പ് നീക്കിയിട്ടുണ്ടെങ്കിൽ, ഇത് ഉപയോഗിക്കരുത്.",
        "നിങ്ങളുടെ അക്കൗണ്ട്",
        "രഹസ്യവാക്ക് രഹസ്യമായി സൂക്ഷിക്കുകയും ഇമെയിൽ വിലാസം നിലവിലുള്ളതാക്കുകയും ചെയ്യുക. നിങ്ങളുടെ അക്കൗണ്ടിലൂടെ ചെയ്യുന്ന കാര്യങ്ങൾ നിങ്ങൾ ചെയ്തതായാണ് കണക്കാക്കുക. അനധികൃത പ്രവേശനം സംശയിച്ചാൽ ഉടൻ അറിയിക്കുക.",
        "നിങ്ങളെക്കുറിച്ചുള്ള കൃത്യമായ വിവരങ്ങൾ നൽകുക. മറ്റൊരാളായി നടിക്കരുത്, മറ്റൊരാൾക്കായി അക്കൗണ്ട് സൃഷ്ടിക്കരുത്, മറ്റൊരാളുടെ ചിത്രമോ തിരിച്ചറിയലോ ഉപയോഗിക്കരുത്.",
        "നിങ്ങളുടെ ഉള്ളടക്കം",
        "നിങ്ങൾ എഴുതുന്നതും അപ്‌ലോഡ് ചെയ്യുന്നതും നിങ്ങളുടെ ഉടമസ്ഥതയിൽ തുടരും. പോസ്റ്റ് ചെയ്യുന്നതിലൂടെ ആപ്പ് പ്രവർത്തിക്കാൻ ആവശ്യമായ രീതിയിൽ സേവനത്തിൽ ഉള്ളടക്കം ഹോസ്റ്റ് ചെയ്യാനും സൂക്ഷിക്കാനും പുനർനിർമ്മിക്കാനും പ്രദർശനത്തിനായി മാറ്റം വരുത്താനും കാണിക്കാനും Go and Help-ന് ലോകവ്യാപകവും ഏകാധിപത്യമില്ലാത്തതും റോയൽറ്റിയില്ലാത്തതുമായ ലൈസൻസ് നൽകുന്നു. നിങ്ങളുടെ ഉള്ളടക്കം എപ്പോൾ വേണമെങ്കിലും മായ്ക്കാം; മറ്റുള്ളവർ ഇതിനകം ഉദ്ധരിച്ചതോ മറുപടി നൽകിയതോ ആയ പകർപ്പുകൾ അവരുടെ പോസ്റ്റുകളിൽ ശേഷിക്കാം.",
        "ഫോട്ടോകൾ ഉൾപ്പെടെ നിങ്ങൾ പോസ്റ്റ് ചെയ്യുന്നതെല്ലാം പ്രസിദ്ധീകരിക്കാൻ നിങ്ങൾക്ക് അവകാശമുണ്ടെന്നും അത് മറ്റൊരാളുടെ അവകാശം ലംഘിക്കുകയോ നിയമം ലംഘിക്കുകയോ ചെയ്യുന്നില്ലെന്നും നിങ്ങൾ ഉറപ്പുനൽകുന്നു. ഈ കരാർ ലംഘിക്കുന്ന ഉള്ളടക്കം ഞങ്ങൾ നീക്കാം; എന്നാൽ ഉള്ളടക്കം മുൻകൂട്ടി പരിശോധിക്കുകയോ അംഗീകരിക്കുകയോ ചെയ്യുന്നില്ല, ഉപയോക്താക്കൾ പ്രസിദ്ധീകരിക്കുന്ന കാര്യങ്ങൾക്ക് ഉത്തരവാദികളുമല്ല.",
        "ഉപയോക്താക്കൾ തമ്മിലുള്ള ക്രമീകരണങ്ങൾ അവരുടെ സ്വന്തം ഉത്തരവാദിത്തം",
        "സഹായിക്കാമെന്നോ സഹായം സ്വീകരിക്കാമെന്നോ യാത്ര ചെയ്യാമെന്നോ കണ്ടുമുട്ടാമെന്നോ എവിടെയെങ്കിലും താമസിക്കാമെന്നോ പ്രതിഫലം നൽകാമെന്നോ സ്വീകരിക്കാമെന്നോ ഉള്ള ധാരണ അതിൽ പങ്കെടുക്കുന്ന ഉപയോക്താക്കൾ തമ്മിൽ നേരിട്ടാണ് ഉണ്ടാകുന്നത്. അത് സ്വകാര്യവും സ്വതന്ത്രവുമായ ക്രമീകരണമാണ്. Go and Help അതിൽ കക്ഷിയല്ല, കമ്മീഷൻ ഈടാക്കുന്നില്ല, അത് നടപ്പാക്കുകയുമില്ല.",
        "ഒരു ക്രമീകരണം നിങ്ങൾക്ക് സുരക്ഷിതവും നിയമാനുസൃതവും അനുയോജ്യവുമാണോ എന്ന് തീരുമാനിക്കേണ്ടതും നിങ്ങൾക്കാണ്; നിങ്ങൾക്ക് ബാധകമായ അനുമതിപത്രം, ലൈസൻസ്, ഇൻഷുറൻസ്, ആരോഗ്യ-സുരക്ഷാ ബാധ്യത, നികുതി, റിപ്പോർട്ടിങ് ചുമതല എന്നിവയും നിങ്ങളുടേതാണ്. ചില രാജ്യങ്ങളിൽ ചില ജോലികൾക്ക് യോഗ്യതയുള്ളതോ ലൈസൻസുള്ളതോ ആയ വ്യക്തി വേണം; ഇവിടെ ഒന്നും അതിൽ മാറ്റം വരുത്തുന്നില്ല.",
        "ആപ്പിൽ വിവരിക്കുന്ന പ്രതിഫലങ്ങൾ ആളുകൾ തമ്മിൽ നന്ദി പ്രകടിപ്പിക്കുന്ന സ്വമേധയാ നൽകുന്ന കാര്യങ്ങളാണ്. Go and Help-നോടോ മറ്റൊരു ഉപയോക്താവിനോടോ നിങ്ങൾക്ക് തൊഴിൽബന്ധമോ പങ്കാളിത്തമോ ഏജൻസി ബന്ധമോ ഫ്രാഞ്ചൈസിയോ സംയുക്ത സംരംഭമോ ഇതിലൂടെ ഉണ്ടാകുന്നില്ല.",
        "പണമടയ്ക്കലും അംഗത്വവും",
        "സഹായം വാഗ്ദാനം ചെയ്യാനും നൽകാനും Go and Help ഉപയോഗിക്കുന്നത് സൗജന്യമാണ്. അംഗത്വം ഐച്ഛികമാണ്; ഞങ്ങളുടെ പണമടയ്ക്കൽ സേവനമായ Stripe ആണ് തുക ഈടാക്കുന്നത്. സ്ഥിരീകരിക്കുന്നതിന് മുമ്പ് വിലകൾ കാണിക്കും. മാസ അംഗത്വം ഓരോ മാസവും സ്വയം പുതുക്കും; വാർഷിക അംഗത്വം ഓരോ വർഷവും സ്വയം പുതുക്കും; നിങ്ങൾ റദ്ദാക്കുന്നതുവരെ ഇത് തുടരും.",
        "ബില്ലിങ് പോർട്ടലിൽനിന്ന് എപ്പോൾ വേണമെങ്കിലും റദ്ദാക്കാം; ഇതിനകം പണം നൽകിയ കാലയളവ് അവസാനിക്കുന്നതുവരെ ആനുകൂല്യങ്ങൾ തുടരും. പ്രാദേശിക നിയമം മറ്റുവിധം ആവശ്യപ്പെടുന്നില്ലെങ്കിൽ കാലയളവിന്റെ ശേഷിച്ച ഭാഗത്തിന് പണം മടക്കിനൽകില്ല. നിങ്ങൾ താമസിക്കുന്നിടത്ത് ബാധകമായ നിയമപരമായ പിൻവലിക്കൽ അല്ലെങ്കിൽ റദ്ദാക്കൽ അവകാശങ്ങൾ തുടർന്നും ബാധകമാണ്.",
        "നിങ്ങളുടെ കാർഡ് വിവരങ്ങൾ ഞങ്ങൾ കൈകാര്യം ചെയ്യുകയോ സൂക്ഷിക്കുകയോ ചെയ്യുന്നില്ല. പണമടയ്ക്കൽ പരാജയപ്പെടുകയോ തിരിച്ചെടുക്കപ്പെടുകയോ ചെയ്താൽ പരിഹരിക്കുന്നതുവരെ പ്രീമിയം ആനുകൂല്യങ്ങൾ നിർത്തിവെച്ചേക്കാം.",
        "സുരക്ഷ നിങ്ങളുടെ കൈകളിലാണ്",
        "ആദ്യം പൊതുസ്ഥലത്ത് കണ്ടുമുട്ടുക. നിങ്ങൾ എവിടേക്കാണ് പോകുന്നതെന്ന് ഒരാളോട് പറയുക. പരിശോധിക്കാനാകാത്ത സ്വകാര്യ വിലാസത്തിലേക്ക് പോകരുത്. മറ്റൊരു ഉപയോക്താവിന് പണമോ നിക്ഷേപമോ രേഖകളോ അക്കൗണ്ട് വിവരങ്ങളോ അയക്കരുത്. സുരക്ഷിതമായി ചെയ്യാൻ കഴിവില്ലാത്ത ജോലി ചെയ്യരുത്; സാഹചര്യം മാറുകയോ തെറ്റായി തോന്നുകയോ ചെയ്താൽ ഉടൻ നിർത്തുക.",
        "ശാരീരികമോ ഘടനാപരമോ വൈദ്യുതമോ യന്ത്രസംബന്ധമോ വൈദ്യപരമോ മൃഗങ്ങളുമായി ബന്ധപ്പെട്ടതോ കുട്ടിപരിചരണവുമായി ബന്ധപ്പെട്ടതോ ആയ ജോലി ചെയ്യുന്നതിനു മുമ്പ് നിങ്ങളുടെ സ്വന്തം ഇൻഷുറൻസ് പരിഗണിക്കുക. കണ്ടുമുട്ടുന്നയാൾക്ക് ഇൻഷുറൻസ് ഉണ്ടോ എന്നും ചിന്തിക്കുക. അടിയന്തര സാഹചര്യത്തിൽ നിങ്ങളുടെ പ്രദേശത്തെ അടിയന്തര സേവനങ്ങളെ വിളിക്കുക — സംഭവസ്ഥലത്ത് സഹായിക്കാൻ ഞങ്ങൾക്ക് കഴിയില്ല.",
        "വിലക്കപ്പെട്ട പെരുമാറ്റം",
        "നിയമവിരുദ്ധമായ കാര്യങ്ങൾക്കായി Go and Help ഉപയോഗിക്കുകയോ അവ ക്രമീകരിക്കുകയോ ചെയ്യരുത്. പ്രത്യേകിച്ച് നിരോധിച്ചിരിക്കുന്നത്: ഉപദ്രവം, ഭീഷണി, വിദ്വേഷ പ്രസംഗം, വിവേചനം, പിന്തുടരൽ, ലൈംഗിക ഉള്ളടക്കമോ സേവനങ്ങളോ, ഏതുവിധത്തിലുള്ള ചൂഷണമോ മനുഷ്യക്കടത്തോ, കുട്ടികളെ അപകടത്തിലാക്കൽ, സഹായമെന്ന പേരിലുള്ള നിർബന്ധിതമോ കൂലിയില്ലാത്തതോ ആയ തൊഴിൽ, ആയുധങ്ങൾ, മയക്കുമരുന്നുകൾ, കടത്ത്, തട്ടിപ്പ്, കള്ളപ്പണം വെളുപ്പിക്കൽ, ഫിഷിങ്, സ്പാം, ബന്ധമില്ലാത്ത വാണിജ്യ സേവനങ്ങളുടെ പരസ്യം, ആപ്പിന്റെ സുരക്ഷയിലോ പ്രവർത്തനത്തിലോ ഇടപെടൽ.",
        "സമ്മതമില്ലാതെ മറ്റൊരാളുടെ സ്വകാര്യ വിവരങ്ങൾ പ്രസിദ്ധീകരിക്കരുത്; ആരെയെങ്കിലും പിന്തുടരാനോ നിരീക്ഷിക്കാനോ സമ്മർദത്തിലാക്കാനോ ഭൂപടമോ തിരച്ചിലോ ഉപയോഗിക്കരുത്.",
        "താൽക്കാലികമായി നിർത്തലാക്കലും നീക്കംചെയ്യലും",
        "ഈ കരാർ ലംഘിച്ചിട്ടുണ്ടെന്ന് യുക്തിപൂർവം വിശ്വസിക്കുന്നുവെങ്കിൽ, നിയമം ആവശ്യപ്പെടുകയാണെങ്കിൽ, മറ്റുള്ളവർക്കോ സേവനത്തിനോ അപകടമുണ്ടെങ്കിൽ ഉള്ളടക്കം നീക്കാനും സൗകര്യങ്ങൾ പരിമിതപ്പെടുത്താനും അക്കൗണ്ട് നിർത്തിവെക്കാനോ അടയ്ക്കാനോ ഞങ്ങൾക്ക് കഴിയും. ന്യായവും നിയമാനുസൃതവുമാണെങ്കിൽ കാരണം അറിയിക്കും; നിങ്ങൾക്ക് മറുപടി നൽകാം.",
        "Go and Help ഉപയോഗിക്കുന്നത് എപ്പോൾ വേണമെങ്കിലും നിർത്തുകയും അക്കൗണ്ട് അടയ്ക്കുകയും ചെയ്യാം.",
        "ബൗദ്ധിക സ്വത്തവകാശം",
        "Go and Help എന്ന പേര്, ലോഗോ, രൂപകൽപ്പന, സോഫ്റ്റ്‌വെയർ എന്നിവ ഞങ്ങളുടെയോ ലൈസൻസ് നൽകിയവരുടെയോ ഉടമസ്ഥതയിലാണ്; ബൗദ്ധിക സ്വത്തവകാശ നിയമങ്ങൾ അവ സംരക്ഷിക്കുന്നു. ആപ്പ് തന്നെ അനുവദിക്കുന്ന രീതിയിൽ മാത്രമേ അവ ഉപയോഗിക്കാവൂ. ഭൂപട വിവരങ്ങളും ഓപ്പൺ സോഴ്‌സ് ഘടകങ്ങളും അവയുടെ സ്വന്തം രചയിതാക്കളുടെ ഉടമസ്ഥതയിൽ തുടരും; അവയുടെ സ്വന്തം ലൈസൻസുകൾക്കു കീഴിലാണ് ഉപയോഗിക്കുന്നത്.",
        "Go and Help-ലെ ഉള്ളടക്കം നിങ്ങളുടെ അവകാശങ്ങൾ ലംഘിക്കുന്നുവെന്ന് കരുതുന്നുവെങ്കിൽ എന്താണെന്നും എവിടെയാണെന്നും അറിയിക്കുക; ഞങ്ങൾ പരിശോധിക്കും.",
        "നിലവിലുള്ളതുപോലെ സേവനം",
        "Go and Help നിലവിലുള്ളതും ലഭ്യമായതുമായ നിലയിലാണ് നൽകുന്നത്. നിങ്ങൾ താമസിക്കുന്നിടത്തെ നിയമം അനുവദിക്കുന്ന പരമാവധി പരിധിയിൽ, ആപ്പ് തടസ്സമില്ലാതെ പ്രവർത്തിക്കുമെന്നും പിശകുകളില്ലെന്നും എല്ലാ ആക്രമണങ്ങളിൽനിന്നും സുരക്ഷിതമാണെന്നും പ്രത്യേക ആവശ്യത്തിന് അനുയോജ്യമാണെന്നും ഞങ്ങൾ ഉറപ്പുനൽകുന്നില്ല; ഉപയോക്താവ് സത്യസന്ധനോ പ്രാവീണ്യമുള്ളവനോ ഇൻഷുറൻസ് ഉള്ളവനോ ലൈസൻസുള്ളവനോ സുരക്ഷിതനോ ആണെന്നും അഭ്യർഥനയോ പ്രതിഫലമോ പ്രൊഫൈലോ കൃത്യമാണെന്നും ഏതെങ്കിലും ക്രമീകരണം പാലിക്കപ്പെടുമെന്നും ഉറപ്പില്ല.",
        "സ്ഥലങ്ങൾ, ദൂരങ്ങൾ, ലഭ്യത, റേറ്റിങ്ങുകൾ എന്നിവ ഉപയോക്താക്കളും മൂന്നാം കക്ഷി ഭൂപട വിവരങ്ങളും നൽകിയതുപോലെ കാണിക്കുന്നു. അവ തെറ്റായതോ കാലഹരണപ്പെട്ടതോ ആയിരിക്കാം.",
        "ബാധ്യതയുടെ പരിമിതി",
        "നിങ്ങൾക്ക് ബാധകമായ നിയമം അനുവദിക്കുന്ന പരമാവധി പരിധിയിൽ, മറ്റ് ഉപയോക്താക്കളോ അവരുടെ പെരുമാറ്റമോ ഉള്ളടക്കമോ, ഉപയോക്താക്കൾ തമ്മിലുള്ള കൂടിക്കാഴ്ചയോ ആശയവിനിമയമോ, യാത്രയോ, ചെയ്തതോ നിരസിച്ചതോ ആയ ജോലിയോ, നൽകിയതോ തടഞ്ഞുവെച്ചതോ ആയ പ്രതിഫലമോ, മൂന്നാം കക്ഷിയുടെ പ്രവൃത്തികളോ മൂലമോ അവയുമായി ബന്ധപ്പെട്ടോ ഉണ്ടാകുന്ന നഷ്ടത്തിനോ നാശത്തിനോ Go and Help-ഉം അതിന്റെ ഉടമകളും ജീവനക്കാരും വിതരണക്കാരും ഉത്തരവാദികളോ ബാധ്യതയുള്ളവരോ അല്ല. ഇതിൽ വ്യക്തിപരമായ പരിക്കോ രോഗമോ മരണമോ; സ്വത്തിന്റെ നഷ്ടമോ മോഷണമോ നാശമോ; സാമ്പത്തിക നഷ്ടം; ലാഭം, അവസരം, ഡാറ്റ എന്നിവ നഷ്ടപ്പെടൽ; മാനസിക വിഷമമോ മറ്റ് വൈകാരിക ദോഷമോ ഉൾപ്പെടുന്നു.",
        "അതേ പരിധിയിൽ പരോക്ഷമോ ആകസ്മികമോ പ്രത്യേകമോ അനന്തരഫലമായോ ശിക്ഷാത്മകമോ ആയ നാശനഷ്ടങ്ങൾക്ക് ഞങ്ങൾ ബാധ്യസ്ഥരല്ല. നിയമപ്രകാരം ബാധ്യത ഒഴിവാക്കാനാവില്ലെങ്കിലും പരിമിതപ്പെടുത്താനാകുന്നിടത്ത്, നിങ്ങളോടുള്ള ഞങ്ങളുടെ ആകെ ബാധ്യതയുടെ പരമാവധി, അവകാശവാദം ഉന്നയിക്കുന്നതിന് മുമ്പുള്ള 12 മാസങ്ങളിൽ നിങ്ങൾ ഞങ്ങൾക്ക് നൽകിയ അംഗത്വ ഫീസും 50 USD-യും തമ്മിൽ ഏതാണ് കൂടുതലോ അതാണ്.",
        "നിയമം ഒഴിവാക്കാനോ പരിമിതപ്പെടുത്താനോ അനുവദിക്കാത്ത ബാധ്യതയെ ഈ കരാറിലെ ഒന്നും ഒഴിവാക്കുകയോ പരിമിതപ്പെടുത്തുകയോ ചെയ്യുന്നില്ല — അനേകം രാജ്യങ്ങളിൽ അശ്രദ്ധമൂലമുള്ള മരണത്തിനോ വ്യക്തിപരമായ പരിക്കിനോ ഉള്ള ബാധ്യത, തട്ടിപ്പോ വഞ്ചനാപരമായ തെറ്റായ പ്രസ്താവനയോ, നിർബന്ധമായ ഉപഭോക്തൃ അവകാശങ്ങൾ എന്നിവ ഇതിൽ ഉൾപ്പെടുന്നു. ഈ വിഭാഗത്തിന്റെ ഏതെങ്കിലും ഭാഗം നടപ്പാക്കാനാവില്ലെന്ന് കോടതി കണ്ടെത്തിയാലും ശേഷിക്കുന്ന ഭാഗം തുടരും; നിങ്ങളുടെ നിർബന്ധിത പ്രാദേശിക അവകാശങ്ങളെ ബാധിക്കില്ല.",
        "നഷ്ടപരിഹാര ഉത്തരവാദിത്തം",
        "നിങ്ങളുടെ ഉള്ളടക്കം, പെരുമാറ്റം, മറ്റ് ഉപയോക്താക്കളുമായുള്ള ക്രമീകരണങ്ങൾ, അല്ലെങ്കിൽ ഈ കരാർ ലംഘിക്കൽ എന്നിവയിൽനിന്ന് ഉയരുന്ന മൂന്നാം കക്ഷിയുടെ അവകാശവാദങ്ങൾക്കും ആവശ്യങ്ങൾക്കും നഷ്ടങ്ങൾക്കും യുക്തമായ ചെലവുകൾക്കും Go and Help-നെ സംരക്ഷിക്കുകയും നഷ്ടപരിഹാരം നൽകുകയും ചെയ്യാമെന്ന് നിങ്ങൾ സമ്മതിക്കുന്നു — നിങ്ങൾ താമസിക്കുന്നിടത്തെ നിയമം ഇത് അനുവദിക്കാത്ത പരിധിയിലോ അവകാശവാദം ഞങ്ങളുടെ സ്വന്തം തെറ്റിൽനിന്ന് ഉണ്ടായതോ ആയാൽ ഒഴികെ.",
        "തർക്കങ്ങളും നിങ്ങളുടെ പ്രാദേശിക അവകാശങ്ങളും",
        "ആദ്യം ഞങ്ങളെ ബന്ധപ്പെടുക: മിക്ക പ്രശ്നങ്ങളും ഇമെയിൽ വഴി പരിഹരിക്കാം. പരിഹരിക്കാനാകുന്നില്ലെങ്കിൽ കോടതിയെ സമീപിക്കുന്നതിന് മുമ്പ് പ്രായോഗികമായ മുന്നോട്ടുള്ള വഴി സത്യസന്ധമായി സമ്മതിക്കാൻ ശ്രമിക്കും.",
        "ഉപയോക്താക്കൾ തമ്മിലുള്ള തർക്കങ്ങൾ അവരുടെ ഇടയിൽത്തന്നെയാണ്. നിയമം ആവശ്യപ്പെടുമ്പോൾ രേഖകൾ നൽകാം; എന്നാൽ മധ്യസ്ഥത വഹിക്കുകയോ വിധി പറയുകയോ നഷ്ടപരിഹാരം നൽകുകയോ ചെയ്യുന്നില്ല.",
        "Go and Help വെബ്‌സൈറ്റിൽ പറഞ്ഞിരിക്കുന്ന നിയമമാണ് ഈ കരാറിനെ നിയന്ത്രിക്കുന്നത്. എന്നാൽ നിങ്ങൾ ഉപഭോക്താവാണെങ്കിൽ, നിങ്ങൾ പതിവായി താമസിക്കുന്ന രാജ്യത്തെ നിർബന്ധിത ഉപഭോക്തൃനിയമത്തിന്റെ സംരക്ഷണമോ നിങ്ങളുടെ പ്രാദേശിക കോടതികളിൽ അവകാശവാദം ഉന്നയിക്കാനുള്ള അവകാശമോ ഇതിലൂടെ നഷ്ടപ്പെടുന്നില്ല. ഈ കരാറിലെ നിബന്ധന നിർബന്ധിത നിയമവുമായി പൊരുത്തപ്പെടുന്നില്ലെങ്കിൽ ആ നിയമത്തിനാണ് മുൻഗണന.",
        "ഈ കരാറിലെ മാറ്റങ്ങൾ",
        "ആപ്പ് മാറുമ്പോഴോ നിയമം ആവശ്യപ്പെടുമ്പോഴോ ഈ കരാർ പുതുക്കാം. പ്രധാനപ്പെട്ട മാറ്റമുണ്ടെങ്കിൽ പുതിയ പ്രാബല്യ തീയതി ഇവിടെ കാണിക്കും; കാര്യമായ മാറ്റങ്ങൾ ആപ്പിൽ അറിയിക്കുകയും ചെയ്യും. മാറ്റത്തിനു ശേഷവും Go and Help ഉപയോഗിക്കുന്നത് പുതുക്കിയ നിബന്ധനകൾ അംഗീകരിക്കുന്നതായിരിക്കും; അംഗീകരിക്കുന്നില്ലെങ്കിൽ അക്കൗണ്ട് അടയ്ക്കുക.",
        "ഈ സ്ക്രീനുകളിലെ ഉള്ളടക്കം രാജ്യാന്തര പ്രേക്ഷകർക്കായുള്ള ആപ്പ് വിവരങ്ങളാണ്. ഏതെങ്കിലും പ്രത്യേക രാജ്യത്തെക്കുറിച്ചുള്ള നിയമോപദേശമല്ല; നിങ്ങൾ താമസിക്കുന്നിടത്തെ യോഗ്യനായ അഭിഭാഷകന്റെ ഉപദേശത്തിന് പകരവുമല്ല.",
    ),
}
